(() => {
'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='APLUS_AI_TUTOR_STUDENT_V6';
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch(e){}
state=state||{level:'P3',questions:0,correct:0,skills:{},mistakes:[],history:[]};
const grammarQuestions=[
['The box of pencils _____ on the table.',['is','are','be','am'],'is','Subject–verb agreement'],
['Every morning, Amir _____ to school.',['walks','walk','walking','walked'],'walks','Present simple'],
['Look! The children _____ football.',['are playing','play','played','have played'],'are playing','Present continuous'],
['Yesterday, we _____ to the museum.',['went','go','gone','going'],'went','Past simple'],
['She has _____ her project already.',['finished','finish','finishing','finishes'],'finished','Present perfect'],
['You _____ wear your seat belt.',['must','must to','musts','must wearing'],'must','Modal verbs'],
['The girl sang _____.',['beautifully','beautiful','beauty','beautify'],'beautifully','Adverbs'],
['The boy _____ won the race is my friend.',['who','which','where','what'],'who','Relative clauses'],
['If it _____, we will stay indoors.',['rains','will rain','rained','raining'],'rains','Conditional sentences'],
['I enjoy _____ storybooks.',['reading','to read','read','reads'],'reading','Gerunds and infinitives'],
['There are _____ books on the shelf.',['three','a','much','one'],'three','Noun forms'],
['Mum gave the book to _____.',['me','I','my','mine'],'me','Object pronouns'],
['She does not _____ coffee.',['drink','drinks','drank','drinking'],'drink','Negative sentences'],
['The cake _____ by Mum yesterday.',['was made','was make','made','is making'],'was made','Passive voice'],
['I went to the library _____ a book.',['to borrow','for borrow','borrowing','borrowed'],'to borrow','Infinitive of purpose']
];
const vocabQuestions=[
['The glass vase is very _____. Handle it carefully.',['fragile','ancient','swift','generous'],'fragile','Vocabulary in context'],
['The runner moved very _____.',['swiftly','fragile','ancient','miserable'],'swiftly','Word meaning'],
['The kind girl was _____ and shared her food.',['generous','fragile','ancient','reluctant'],'generous','Word meaning'],
['The old temple is very _____.',['ancient','swift','generous','fragile'],'ancient','Word meaning'],
['He was _____ to speak in front of the crowd because he felt shy.',['reluctant','substantial','meticulous','fortunate'],'reluctant','Vocabulary in context'],
['The student was _____ and checked every detail carefully.',['meticulous','swift','ancient','miserable'],'meticulous','Word meaning'],
['We were _____ to have found shelter before the storm.',['fortunate','fragile','reluctant','scarce'],'fortunate','Word meaning'],
['Clean water became _____ during the drought.',['scarce','generous','swift','ancient'],'scarce','Vocabulary in context'],
['The medicine helped to _____ her pain.',['relieve','deteriorate','whisper','persist'],'relieve','Word meaning'],
['The building began to _____ after years without repairs.',['deteriorate','relieve','whisper','celebrate'],'deteriorate','Word meaning']
];
let session={list:[],index:0,mode:'',correct:0,wrong:0};
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function skill(name){return state.skills[name]||{correct:0,total:0,mastery:0}}
function updateSkill(name,ok){let s=skill(name);s.total++;if(ok)s.correct++;s.mastery=Math.round(s.correct/s.total*100);state.skills[name]=s}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function update(){ $('statQuestions').textContent=state.questions;$('statAccuracy').textContent=state.questions?Math.round(state.correct/state.questions*100)+'%':'—';let a=Object.values(state.skills);$('statMastery').textContent=a.length?Math.round(a.reduce((n,s)=>n+s.mastery,0)/a.length)+'%':'0%';$('statReview').textContent=state.mistakes.length;$('dataStatus').textContent='Tutor Brain V6 ready · '+state.level;$('coachMessage').textContent=state.questions?'Your recent results are shaping the next practice.':'Let’s begin with one clear step.';let names=['Grammar','Vocabulary in context','Word meaning'];$('skillsList').innerHTML=names.map(n=>{let s=skill(n);return '<div class="skill-row"><div class="skill-head"><span>'+n+'</span><span>'+s.mastery+'%</span></div><div class="bar"><span style="width:'+s.mastery+'%"></span></div></div>'}).join('');$('reviewList').innerHTML=state.mistakes.length?state.mistakes.slice(0,3).map(m=>'<div class="review-item"><span class="dot"></span><div><b>'+esc(m.skill)+'</b><small>'+esc(m.topic||'Review needed')+'</small></div></div>').join(''):'<div class="review-item"><span class="dot"></span><div><b>No review items yet.</b><small>Complete a practice session to build your review list.</small></div></div>';$('pathList').innerHTML='<div class="path-item"><span class="dot"></span><div><b>1. Understand</b><small>Read the sentence and identify the clue.</small></div></div><div class="path-item"><span class="dot"></span><div><b>2. Practise</b><small>Try a similar question with support.</small></div></div><div class="path-item"><span class="dot"></span><div><b>3. Transfer</b><small>Use the skill in a new context.</small></div></div>'}
function start(mode){session={list:shuffle(mode==='grammar'?grammarQuestions:mode==='vocabulary'?vocabQuestions:shuffle([...grammarQuestions,...vocabQuestions])),index:0,mode,correct:0,wrong:0};render()}
function finish(){let total=session.correct+session.wrong,percent=total?Math.round(session.correct/total*100):0;let heading,body;if(!total){heading='No practice completed';body='No question was answered. Choose a practice mode to begin.'}else if(percent===100){heading='Excellent accuracy';body='You answered every question correctly. The next session can introduce a new skill or a higher challenge.'}else if(percent>=80){heading='Strong progress';body='You answered '+session.correct+' of '+total+' questions correctly. Review the few mistakes before moving to a harder challenge.'}else if(percent>=50){heading='More practice needed';body='You answered '+session.correct+' of '+total+' questions correctly. Let’s revisit the weak skills with guided practice.'}else{heading='Let’s rebuild the basics';body='You answered '+session.correct+' of '+total+' questions correctly. That is useful information: we should slow down, explain the rule, and practise easier examples before increasing difficulty.'}$('quizLabel').textContent='SESSION COMPLETE';$('questionProgress').textContent='Tutor Brain updated';$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">'+(percent>=80?'✓':'↻')+'</div><h3>'+heading+'</h3><p>'+body+'</p><p><strong>Session result: '+session.correct+'/'+total+' correct · '+percent+'%</strong></p><p>Accuracy is feedback, not a judgement. Your next practice will focus on what you need next.</p></div>';update()}
function render(){let q=session.list[session.index];if(!q)return finish();$('quizLabel').textContent=q[3].toUpperCase();$('questionProgress').textContent='Question '+(session.index+1)+' of '+session.list.length+' · '+state.level;$('questionArea').innerHTML='<div class="question-text">'+esc(q[0])+'</div><div class="options">'+shuffle(q[1]).map((o,i)=>'<button class="option-btn" type="button" data-answer="'+esc(o)+'"><b>'+String.fromCharCode(65+i)+'.</b> '+esc(o)+'</button>').join('')+'</div><div id="feedbackSlot"></div>';$('questionArea').querySelectorAll('.option-btn').forEach(b=>b.onclick=()=>answer(q,b))}
function answer(q,b){let chosen=b.dataset.answer,ok=chosen===q[2];$('questionArea').querySelectorAll('.option-btn').forEach(x=>{x.disabled=true;if(x.dataset.answer===q[2])x.classList.add('correct')});if(!ok)b.classList.add('wrong');state.questions++;if(ok){state.correct++;session.correct++}else{session.wrong++;state.mistakes.unshift({skill:q[3],topic:q[0],answer:q[2],at:Date.now()});state.mistakes=state.mistakes.slice(0,50)}updateSkill(q[3],ok);state.history.unshift({ok,skill:q[3],at:Date.now()});save();let feedback=ok?'Correct. You identified the form that fits the sentence.':'Not correct yet. The answer is “'+q[2]+'”. Read the sentence again and look for the grammar or meaning clue.';$('feedbackSlot').innerHTML='<div class="feedback '+(ok?'feedback-good':'feedback-fix')+'"><b>'+(ok?'Correct!':'Let’s learn from this.')+'</b><br>'+esc(feedback)+'</div><div class="feedback-actions"><button class="next-btn" id="nextQuestion" type="button">'+(session.index+1===session.list.length?'See session result':'Next question')+' →</button></div>';$('nextQuestion').onclick=()=>{session.index++;render()};update()}
document.querySelectorAll('.level-btn').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;document.querySelectorAll('.level-btn').forEach(x=>x.classList.toggle('active',x===b));save();update()});document.querySelectorAll('.practice-card').forEach(b=>b.onclick=()=>{start(b.dataset.mode);$('quizCard').scrollIntoView({behavior:'smooth',block:'start'})});$('closeQuiz').onclick=()=>{$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">✦</div><h3>Your next question is waiting.</h3><p>Choose a practice mode above.</p></div>'};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='challenge')start('mixed');else if(a==='easier')start('review');else if(a==='another')start('vocabulary');else if(a==='explain'){let m=state.mistakes[0];$('questionArea').innerHTML=m?'<div class="feedback"><b>Let’s review this mistake</b><br>'+esc(m.topic)+'<br><small>Expected answer: '+esc(m.answer)+'</small></div>':'<div class="feedback"><b>No mistake has been recorded yet.</b><br>Complete a question first.</div>'}});$('resetBtn').onclick=()=>{localStorage.removeItem(KEY);location.reload()};update();
})();
